macro_rules! deps {
    () => {
        Data!();
        Error!();
    };
}

macro_rules! tests {
    () => {
        deps!();
        # [cfg (test)] mod tests { use super :: * ; use proptest :: prelude :: * ; fn str (i : & [u8]) -> & str { :: std :: str :: from_utf8 (i) . unwrap () } # [test] fn insert_at_beginning () { let mut d = Data :: new (b"foo bar baz") ; d . replace_range (0 .. 0 , b"oh no ") . unwrap () ; assert_eq ! ("oh no foo bar baz" , str (& d . to_vec ())) ; } # [test] fn insert_at_end () { let mut d = Data :: new (b"foo bar baz") ; d . replace_range (11 .. 11 , b" oh no") . unwrap () ; assert_eq ! ("foo bar baz oh no" , str (& d . to_vec ())) ; } # [test] fn replace_some_stuff () { let mut d = Data :: new (b"foo bar baz") ; d . replace_range (4 .. 7 , b"lol") . unwrap () ; assert_eq ! ("foo lol baz" , str (& d . to_vec ())) ; } # [test] fn replace_a_single_char () { let mut d = Data :: new (b"let y = true;") ; d . replace_range (4 .. 5 , b"mut y") . unwrap () ; assert_eq ! ("let mut y = true;" , str (& d . to_vec ())) ; } # [test] fn replace_multiple_lines () { let mut d = Data :: new (b"lorem\nipsum\ndolor") ; d . replace_range (6 .. 11 , b"lol") . unwrap () ; assert_eq ! ("lorem\nlol\ndolor" , str (& d . to_vec ())) ; d . replace_range (12 .. 17 , b"lol") . unwrap () ; assert_eq ! ("lorem\nlol\nlol" , str (& d . to_vec ())) ; } # [test] fn replace_multiple_lines_with_insert_only () { let mut d = Data :: new (b"foo!") ; d . replace_range (3 .. 3 , b"bar") . unwrap () ; assert_eq ! ("foobar!" , str (& d . to_vec ())) ; d . replace_range (0 .. 3 , b"baz") . unwrap () ; assert_eq ! ("bazbar!" , str (& d . to_vec ())) ; d . replace_range (3 .. 4 , b"?") . unwrap () ; assert_eq ! ("bazbar?" , str (& d . to_vec ())) ; } # [test] # [allow (clippy :: reversed_empty_ranges)] fn replace_invalid_range () { let mut d = Data :: new (b"foo!") ; assert ! (d . replace_range (2 .. 1 , b"bar") . is_err ()) ; assert ! (d . replace_range (0 .. 3 , b"bar") . is_ok ()) ; } # [test] fn empty_to_vec_roundtrip () { let s = "" ; assert_eq ! (s . as_bytes () , Data :: new (s . as_bytes ()) . to_vec () . as_slice ()) ; } # [test] fn replace_same_range_diff_data () { let mut d = Data :: new (b"foo bar baz") ; d . replace_range (4 .. 7 , b"lol") . unwrap () ; assert_eq ! ("foo lol baz" , str (& d . to_vec ())) ; assert ! (matches ! (d . replace_range (4 .. 7 , b"lol2") . unwrap_err () , Error :: AlreadyReplaced { is_identical : false , .. } ,)) ; } # [test] fn replace_same_range_same_data () { let mut d = Data :: new (b"foo bar baz") ; d . replace_range (4 .. 7 , b"lol") . unwrap () ; assert_eq ! ("foo lol baz" , str (& d . to_vec ())) ; assert ! (matches ! (d . replace_range (4 .. 7 , b"lol") . unwrap_err () , Error :: AlreadyReplaced { is_identical : true , .. } ,)) ; } # [test] fn broken_replacements () { let mut d = Data :: new (b"foo") ; assert ! (matches ! (d . replace_range (4 .. 8 , b"lol") . unwrap_err () , Error :: DataLengthExceeded (std :: ops :: Range { start : 4 , end : 8 } , 3) ,)) ; } # [test] fn insert_same_twice () { let mut d = Data :: new (b"foo") ; d . replace_range (1 .. 1 , b"b") . unwrap () ; assert_eq ! ("fboo" , str (& d . to_vec ())) ; assert ! (matches ! (d . replace_range (1 .. 1 , b"b") . unwrap_err () , Error :: AlreadyReplaced { is_identical : true , .. } ,)) ; assert_eq ! ("fboo" , str (& d . to_vec ())) ; } # [test] fn commit_restore () { let mut d = Data :: new (b", ") ; assert_eq ! (", " , str (& d . to_vec ())) ; d . replace_range (2 .. 2 , b"world") . unwrap () ; d . replace_range (0 .. 0 , b"hello") . unwrap () ; assert_eq ! ("hello, world" , str (& d . to_vec ())) ; d . restore () ; assert_eq ! (", " , str (& d . to_vec ())) ; d . commit () ; assert_eq ! (", " , str (& d . to_vec ())) ; d . replace_range (2 .. 2 , b"world") . unwrap () ; assert_eq ! (", world" , str (& d . to_vec ())) ; d . commit () ; assert_eq ! (", world" , str (& d . to_vec ())) ; d . restore () ; assert_eq ! (", world" , str (& d . to_vec ())) ; d . replace_range (0 .. 0 , b"hello") . unwrap () ; assert_eq ! ("hello, world" , str (& d . to_vec ())) ; d . commit () ; assert_eq ! ("hello, world" , str (& d . to_vec ())) ; d . restore () ; assert_eq ! ("hello, world" , str (& d . to_vec ())) ; } proptest ! { # [test] fn new_to_vec_roundtrip (ref s in "\\PC*") { assert_eq ! (s . as_bytes () , Data :: new (s . as_bytes ()) . to_vec () . as_slice ()) ; } # [test] fn replace_random_chunks (ref data in "\\PC*" , ref replacements in prop :: collection :: vec ((any ::<:: std :: ops :: Range < usize >> () , any ::< Vec < u8 >> ()) , 1 .. 100 ,)) { let mut d = Data :: new (data . as_bytes ()) ; for & (ref range , ref bytes) in replacements { let _ = d . replace_range (range . clone () , bytes) ; } } } }
    };
}

tests!();